   204→      '<p class="zcc-heading">' + esc(cfg.heading) + "</p>" +
   205→      '<div class="zcc-row">' +
   206→        '<input class="zcc-input" type="text" id="' + wid + '-inp"' +
   207→          ' placeholder="' + escAttr(cfg.placeholder) + '"' +
   208→          ' aria-label="' + escAttr(cfg.placeholder) + '" />' +
