   215→  function wireWidget(wid, cfg, API_BASE, SHOP) {
   216→    var inp = document.getElementById(wid + "-inp");
   217→    var btn = document.getElementById(wid + "-btn");
   218→    var res = document.getElementById(wid + "-res");
   219→    var btnLabel = cfg.buttonText;
   220→    if (!inp || !btn || !res) return;
   221→
   222→    function normalizeZip(raw) {
   223→      var z = raw.trim().toUpperCase();
   224→      z = z.replace(/\s+/g, '');        // collapse all spaces (UK: SW1A 2AA → SW1A2AA)
   225→      z = z.replace(/-\d{4}$/, '');     // strip US ZIP+4 suffix (90210-1234 → 90210)
   226→      return z;
   227→    }
   228→
   229→    function checkZip() {
   230→      var zip = normalizeZip(inp.value);
   231→      inp.value = zip;  // Update the input field to show the normalized value (clean UX)
   232→      if (!zip) { inp.focus(); return; }
   233→
   234→      btn.disabled = true;
   235→      btn.textContent = "\u2026";
   236→      res.innerHTML = "";
   237→
   238→      fetch(
   239→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
   240→          "&zip=" + encodeURIComponent(zip)
   241→      )
   242→        .then(function (r) { return r.json(); })
   243→        .then(function (data) {
   244→          btn.disabled = false;
   245→          btn.textContent = btnLabel;
   246→
   247→          // Store validation result for cart page
   248→          try {
   249→            sessionStorage.setItem('zcc:valid', data.allowed ? 'true' : 'false');
   250→            sessionStorage.setItem('zcc:zip', zip);
   251→            sessionStorage.setItem('zcc:shop', SHOP);
   252→            // Fire custom event for other scripts to listen to
   253→            window.dispatchEvent(new CustomEvent('zcc:validated', {
   254→              detail: { valid: data.allowed, zip: zip }
   255→            }));
   256→          } catch(e) { /* sessionStorage may be unavailable */ }
   257→
   258→          if (data.allowed) {
   259→            var html = '<div class="zcc-result ok">' + esc(data.message);
   260→            if (cfg.showEta && data.eta) {
   261→              html += '<div class="zcc-meta">Estimated delivery: ' + esc(data.eta) + "</div>";
   262→            }
   263→            if (cfg.showZone && data.zone) {
   264→              html += '<div class="zcc-meta">Zone: ' + esc(data.zone) + "</div>";
   265→            }
   266→            if (cfg.showDeliveryDays && data.daysOfWeek) {
   267→              var days = data.daysOfWeek.split(',').map(function(d) { return d.trim(); }).join(' \u00b7 ');
   268→              html += '<div class="zcc-meta zcc-days">Delivers: ' + esc(days) + '</div>';
   269→            }
   270→            if (cfg.showCutoffTime && data.cutoffTime) {
   271→              var parts = data.cutoffTime.split(':');
   272→              var hr = parseInt(parts[0], 10);
   273→              var min = parts[1] || '00';
   274→              var ampm = hr >= 12 ? 'PM' : 'AM';
   275→              var hr12 = hr % 12 || 12;
   276→              html += '<div class="zcc-meta zcc-cutoff">Order by ' + hr12 + ':' + min + ' ' + ampm + ' for same-day delivery</div>';
   277→            }
   278→            if (data.codAvailable === true) {
   279→              html += '<div class="zcc-cod zcc-cod--available">\u2713 Cash on Delivery Available</div>';
   280→            } else if (data.codAvailable === false) {
   281→              html += '<div class="zcc-cod zcc-cod--unavailable">\u2717 COD Not Available</div>';
   282→            }
   283→            if (data.returnPolicy) {
   284→              html += '<div class="zcc-return-policy">\u21a9 ' + esc(data.returnPolicy) + '</div>';
   285→            }
   286→            html += "</div>";
   287→            res.innerHTML = html;
   288→          } else {
   289→            var html = '<div class="zcc-result fail">' + esc(data.message);
   290→            if (cfg.showWaitlistOnFailure) {
   291→              html +=
   292→                '<div class="zcc-wl">' +
   293→                '<input class="zcc-wl-input" type="email" id="' + wid + '-wl-email" placeholder="Enter email to join waitlist" />' +
   294→                '<button class="zcc-wl-btn" id="' + wid + '-wl-btn" type="button">Join Waitlist</button>' +
   295→                "</div>";
   296→            }
   297→            html += "</div>";
   298→            res.innerHTML = html;
   299→
   300→            if (cfg.showWaitlistOnFailure) {
   301→              // Social proof count — insert before email input
   302→              if (cfg.showSocialProof && data.waitlistCount && data.waitlistCount > 0) {
   303→                var wlSection = document.getElementById(wid + "-wl-email");
   304→                if (wlSection && wlSection.parentNode) {
   305→                  var spEl = document.createElement('div');
   306→                  spEl.className = 'zcc-social-proof';
   307→                  var count = data.waitlistCount;
   308→                  spEl.textContent = '\uD83D\uDE4B Join ' + count + ' other' + (count !== 1 ? 's' : '') + ' waiting for delivery to your area';
   309→                  wlSection.parentNode.insertBefore(spEl, wlSection);
   310→                }
   311→              }
   312→
   313→              var wBtn = document.getElementById(wid + "-wl-btn");
   314→              if (wBtn) {
   315→                wBtn.addEventListener("click", function () {
   316→                  var emailEl = document.getElementById(wid + "-wl-email");
   317→                  var email = emailEl ? emailEl.value.trim() : "";
   318→                  if (!email) { if (emailEl) emailEl.focus(); return; }
   319→                  joinWaitlist(zip, email, wBtn);
   320→                });
   321→              }
   322→            }
   323→          }
   324→
   325→          // Block/unblock Add to Cart based on result (if merchant enabled this)
   326→          if (cfg.blockCartOnInvalid) {
   327→            var ATC_SELECTORS = [
   328→              'button[name="add"]',
   329→              '.product-form__submit',
   330→              '[data-product-add]',
   331→              '.btn--add-to-cart',
   332→              '.product-form button[type="submit"]',
   333→              'button.shopify-payment-button__button',
   334→              '.shopify-payment-button button',
   335→              'button.product-form__cart-submit'
   336→            ].join(',');
   337→
   338→            try {
   339→              var atcBtns = document.querySelectorAll(ATC_SELECTORS);
   340→              atcBtns.forEach(function(b) {
   341→                if (!b.closest('#zcc-widget, [data-zcc-widget]')) { // Don't touch our own widget's button
   342→                  if (data.allowed) {
   343→                    b.disabled = false;
   344→                    b.style.opacity = '';
   345→                    b.title = b.getAttribute('data-zcc-orig-title') || '';
   346→                    b.removeAttribute('data-zcc-orig-title');
   347→                    b.removeAttribute('data-zcc-blocked');
   348→                  } else {
   349→                    b.setAttribute('data-zcc-orig-title', b.title || '');
   350→                    b.disabled = true;
   351→                    b.style.opacity = '0.5';
   352→                    b.title = 'Please enter a valid ZIP code to continue';
   353→                    b.setAttribute('data-zcc-blocked', 'true');
   354→                  }
   355→                }
   356→              });
   357→            } catch(e) { /* DOM query may fail in some contexts */ }
   358→          }
   359→        })
   360→        .catch(function () {
   361→          btn.disabled = false;
   362→          btn.textContent = btnLabel;
   363→          res.innerHTML = '<div class="zcc-result fail">Something went wrong. Please try again.</div>';
   364→          try {
   365→            sessionStorage.setItem('zcc:valid', 'false');
   366→            window.dispatchEvent(new CustomEvent('zcc:validated', { detail: { valid: false, zip: zip } }));
   367→          } catch(e) {}
   368→        });
   369→    }
   370→
   371→    btn.addEventListener("click", checkZip);
   372→    inp.addEventListener("keydown", function (e) {
   373→      if (e.key === "Enter") checkZip();
   374→    });
   375→
   376→    // Re-enable buttons when customer clears the input
   377→    inp.addEventListener('input', function() {
   378→      if (!inp.value.trim() && cfg.blockCartOnInvalid) {
   379→        try {
   380→          var blocked = document.querySelectorAll('[data-zcc-blocked="true"]');
   381→          blocked.forEach(function(b) {
   382→            b.disabled = false;
   383→            b.style.opacity = '';
   384→            b.title = b.getAttribute('data-zcc-orig-title') || '';
   385→            b.removeAttribute('data-zcc-blocked');
   386→            b.removeAttribute('data-zcc-orig-title');
   387→          });
   388→          sessionStorage.removeItem('zcc:valid');
   389→          sessionStorage.removeItem('zcc:zip');
   390→        } catch(e) {}
   391→      }
   392→    });
   393→  }
