   395→  function joinWaitlist(zip, email, wBtn) {
   396→    wBtn.disabled = true;
   397→    wBtn.textContent = "Joining\u2026";
   398→
   399→    fetch(API_BASE + "/api/waitlist", {
   400→      method: "POST",
   401→      headers: { "Content-Type": "application/json" },
   402→      body: JSON.stringify({ shop: SHOP, zip: zip, email: email }),
   403→    })
   404→      .then(function (r) { return r.json(); })
   405→      .then(function (data) {
   406→        var wlEl = wBtn.closest(".zcc-wl");
   407→        if (data.success) {
   408→          if (wlEl) wlEl.innerHTML =
   409→            '<p style="font-size:13px;margin:6px 0 0">' +
   410→            "\u2713 You\u2019ve been added to the waitlist!" +
   411→            "</p>";
   412→        } else {
   413→          wBtn.disabled = false;
   414→          wBtn.textContent = "Join Waitlist";
   415→        }
   416→      })
   417→      .catch(function () {
   418→        wBtn.disabled = false;
   419→        wBtn.textContent = "Join Waitlist";
   420→      });
   421→  }
